using System;
using UnityEngine;
using Framework.Input;

namespace Game.Tests
{
    /// <summary>
    /// 入力方向変換ユーティリティの動作確認用クラス。
    /// </summary>
    public class InputDirectionUtilityTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("テスト設定")]

        /// <summary>
        /// シーン開始時にテストを実行するか。
        /// </summary>
        [SerializeField]
        [Tooltip("開始時に全自動テストを実行する")]
        private bool runTestsOnStart = true;

        #endregion

        #region Runtime Fields

        /// <summary>
        /// 成功したテスト項目数。
        /// </summary>
        private int passedCount;

        /// <summary>
        /// 失敗したテスト項目数。
        /// </summary>
        private int failedCount;

        #endregion

        #region Unity Methods

        /// <summary>
        /// シーン開始時の処理。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        #endregion

        #region Test Methods

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("テスト/全自動テストを実行する")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            TestDeadZone();
            TestScaledDeadZone();
            TestFourDirection();
            TestDirectionPriority();
            TestEightDirection();
            TestDirectionValidation();
            TestInvalidInput();

            PrintTestResult();
        }

        /// <summary>
        /// 通常のデッドゾーン処理を検証する。
        /// </summary>
        private void TestDeadZone()
        {
            Check(
                InputDirectionUtility.IsInDeadZone(
                    Vector2.zero),
                "無入力の判定");

            Check(
                InputDirectionUtility.IsInDeadZone(
                    new Vector2(0.1f, 0.1f)),
                "微小入力の判定");

            Check(
                !InputDirectionUtility.IsInDeadZone(
                    new Vector2(0.5f, 0f)),
                "有効入力の判定");

            Check(
                InputDirectionUtility.ApplyDeadZone(
                    new Vector2(0.1f, 0f)) ==
                    Vector2.zero,
                "デッドゾーン内の入力除去");

            Check(
                InputDirectionUtility.ApplyDeadZone(
                    new Vector2(0.5f, 0.2f)) ==
                    new Vector2(0.5f, 0.2f),
                "デッドゾーン外の入力維持");

            Check(
                InputDirectionUtility.IsInDeadZone(
                    new Vector2(0.3f, 0f), 0.3f),
                "デッドゾーン境界の判定");
        }

        /// <summary>
        /// スケーリング付きデッドゾーンを検証する。
        /// </summary>
        private void TestScaledDeadZone()
        {
            Check(
                InputDirectionUtility.ApplyScaledDeadZone(
                    new Vector2(0.1f, 0f)) ==
                    Vector2.zero,
                "補正時の微小入力除去");

            Check(
                Approximately(
                    InputDirectionUtility.ApplyScaledDeadZone(
                        new Vector2(0.65f, 0f), 0.3f),
                    new Vector2(0.5f, 0f)),
                "デッドゾーン外の入力再割り当て");

            Check(
                Approximately(
                    InputDirectionUtility.ApplyScaledDeadZone(
                        Vector2.right),
                    Vector2.right),
                "最大入力値の維持");

            Check(
                Approximately(
                    InputDirectionUtility.ApplyScaledDeadZone(
                        new Vector2(2f, 0f)),
                    Vector2.right),
                "最大入力値の制限");

            // 斜め入力の方向が維持されるか確認する。
            Vector2 input = new Vector2(0.6f, 0.6f);

            Vector2 result =
                InputDirectionUtility.ApplyScaledDeadZone(
                    input);

            Check(
                Approximately(
                    result.normalized,
                    input.normalized),
                "入力方向の維持");
        }

        /// <summary>
        /// 4方向への変換を検証する。
        /// </summary>
        private void TestFourDirection()
        {
            Check(
                InputDirectionUtility.ToFourDirection(
                    Vector2.up) == Vector2Int.up,
                "上方向変換");

            Check(
                InputDirectionUtility.ToFourDirection(
                    Vector2.down) == Vector2Int.down,
                "下方向変換");

            Check(
                InputDirectionUtility.ToFourDirection(
                    Vector2.left) == Vector2Int.left,
                "左方向変換");

            Check(
                InputDirectionUtility.ToFourDirection(
                    Vector2.right) == Vector2Int.right,
                "右方向変換");

            Check(
                InputDirectionUtility.ToFourDirection(
                    new Vector2(0.8f, 0.2f)) ==
                    Vector2Int.right,
                "強い水平入力の採用");

            Check(
                InputDirectionUtility.ToFourDirection(
                    new Vector2(0.2f, 0.8f)) ==
                    Vector2Int.up,
                "強い垂直入力の採用");

            Check(
                InputDirectionUtility.ToFourDirection(
                    new Vector2(-0.8f, -0.2f)) ==
                    Vector2Int.left,
                "負の水平入力の採用");

            Check(
                InputDirectionUtility.ToFourDirection(
                    new Vector2(-0.2f, -0.8f)) ==
                    Vector2Int.down,
                "負の垂直入力の採用");

            Check(
                InputDirectionUtility.ToFourDirection(
                    Vector2.zero) == Vector2Int.zero,
                "無入力時の方向変換");

            Check(
                InputDirectionUtility.ToFourDirection(
                    new Vector2(0.1f, 0.1f)) ==
                    Vector2Int.zero,
                "微小入力時の方向変換");
        }

        /// <summary>
        /// 斜め入力時の優先方向を検証する。
        /// </summary>
        private void TestDirectionPriority()
        {
            Vector2 input = new Vector2(0.7f, 0.7f);

            Check(
                InputDirectionUtility.ToFourDirection(
                    input,
                    priority: DirectionPriority.Horizontal) ==
                    Vector2Int.right,
                "水平方向優先");

            Check(
                InputDirectionUtility.ToFourDirection(
                    input,
                    priority: DirectionPriority.Vertical) ==
                    Vector2Int.up,
                "垂直方向優先");

            Check(
                InputDirectionUtility.ToFourDirection(
                    input,
                    priority:
                        DirectionPriority.PreviousDirection,
                    previousDirection: Vector2Int.up) ==
                    Vector2Int.up,
                "前回の上方向を維持");

            Check(
                InputDirectionUtility.ToFourDirection(
                    input,
                    priority:
                        DirectionPriority.PreviousDirection,
                    previousDirection: Vector2Int.right) ==
                    Vector2Int.right,
                "前回の右方向を維持");

            Check(
                InputDirectionUtility.ToFourDirection(
                    input,
                    priority:
                        DirectionPriority.PreviousDirection,
                    previousDirection: Vector2Int.left) ==
                    Vector2Int.right,
                "候補外の前回方向を無視");

            Check(
                InputDirectionUtility.ToFourDirection(
                    new Vector2(0.7f, 0.72f),
                    priority:
                        DirectionPriority.PreviousDirection,
                    previousDirection: Vector2Int.right) ==
                    Vector2Int.right,
                "許容差内での前回方向維持");

            Check(
                InputDirectionUtility.ToFourDirection(
                    new Vector2(0.2f, 0.9f),
                    priority:
                        DirectionPriority.PreviousDirection,
                    previousDirection: Vector2Int.right) ==
                    Vector2Int.up,
                "明確に強い入力方向の採用");
        }

        /// <summary>
        /// 8方向への変換を検証する。
        /// </summary>
        private void TestEightDirection()
        {
            Check(
                InputDirectionUtility.ToEightDirection(
                    Vector2.right) == Vector2Int.right,
                "8方向変換：右");

            Check(
                InputDirectionUtility.ToEightDirection(
                    new Vector2(1f, 1f)) ==
                    new Vector2Int(1, 1),
                "8方向変換：右上");

            Check(
                InputDirectionUtility.ToEightDirection(
                    Vector2.up) == Vector2Int.up,
                "8方向変換：上");

            Check(
                InputDirectionUtility.ToEightDirection(
                    new Vector2(-1f, 1f)) ==
                    new Vector2Int(-1, 1),
                "8方向変換：左上");

            Check(
                InputDirectionUtility.ToEightDirection(
                    Vector2.left) == Vector2Int.left,
                "8方向変換：左");

            Check(
                InputDirectionUtility.ToEightDirection(
                    new Vector2(-1f, -1f)) ==
                    new Vector2Int(-1, -1),
                "8方向変換：左下");

            Check(
                InputDirectionUtility.ToEightDirection(
                    Vector2.down) == Vector2Int.down,
                "8方向変換：下");

            Check(
                InputDirectionUtility.ToEightDirection(
                    new Vector2(1f, -1f)) ==
                    new Vector2Int(1, -1),
                "8方向変換：右下");

            Check(
                InputDirectionUtility.ToEightDirection(
                    Vector2.zero) == Vector2Int.zero,
                "8方向変換：無入力");
        }

        /// <summary>
        /// 方向判定処理を検証する。
        /// </summary>
        private void TestDirectionValidation()
        {
            Check(
                InputDirectionUtility.IsFourDirection(
                    Vector2Int.up),
                "有効な4方向の判定");

            Check(
                !InputDirectionUtility.IsFourDirection(
                    new Vector2Int(1, 1)),
                "4方向での斜め入力拒否");

            Check(
                InputDirectionUtility.IsEightDirection(
                    new Vector2Int(1, 1)),
                "有効な8方向の判定");

            Check(
                !InputDirectionUtility.IsEightDirection(
                    new Vector2Int(2, 1)),
                "単位方向以外の拒否");

            Check(
                !InputDirectionUtility.IsEightDirection(
                    Vector2Int.zero),
                "無方向の拒否");

            Check(
                InputDirectionUtility.IsDiagonalDirection(
                    new Vector2Int(-1, 1)),
                "斜め方向の判定");

            Check(
                !InputDirectionUtility.IsDiagonalDirection(
                    Vector2Int.up),
                "直線方向の斜め判定拒否");

            Check(
                InputDirectionUtility.IsOppositeDirection(
                    Vector2Int.left,
                    Vector2Int.right),
                "逆方向の判定");

            Check(
                !InputDirectionUtility.IsOppositeDirection(
                    Vector2Int.up,
                    Vector2Int.right),
                "直交方向の逆方向判定拒否");

            Check(
                !InputDirectionUtility.IsOppositeDirection(
                    Vector2Int.zero,
                    Vector2Int.zero),
                "無方向の逆方向判定拒否");
        }

        /// <summary>
        /// 不正な入力値と設定値を検証する。
        /// </summary>
        private void TestInvalidInput()
        {
            Check(
                InputDirectionUtility.ToFourDirection(
                    new Vector2(float.NaN, 0f)) ==
                    Vector2Int.zero,
                "NaN入力の除去");

            Check(
                InputDirectionUtility.ToEightDirection(
                    new Vector2(
                        float.PositiveInfinity, 0f)) ==
                    Vector2Int.zero,
                "無限大入力の除去");

            CheckThrows<ArgumentOutOfRangeException>(
                () => InputDirectionUtility.ApplyDeadZone(
                    Vector2.right, -0.1f),
                "負のデッドゾーンの拒否");

            CheckThrows<ArgumentOutOfRangeException>(
                () => InputDirectionUtility.ApplyDeadZone(
                    Vector2.right, 1f),
                "範囲外デッドゾーンの拒否");

            CheckThrows<ArgumentOutOfRangeException>(
                () => InputDirectionUtility.ToFourDirection(
                    Vector2.right,
                    tieTolerance: -0.1f),
                "不正な許容差の拒否");

            CheckThrows<ArgumentOutOfRangeException>(
                () => InputDirectionUtility.ToFourDirection(
                    Vector2.right,
                    priority: (DirectionPriority)999),
                "不正な優先方向の拒否");
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 2つのベクトルが許容誤差内で一致するか確認する。
        /// </summary>
        /// <param name="first">比較元のベクトル</param>
        /// <param name="second">比較先のベクトル</param>
        /// <returns>一致する場合はtrue</returns>
        private bool Approximately(
            Vector2 first,
            Vector2 second)
        {
            return Vector2.Distance(first, second) < 0.001f;
        }

        /// <summary>
        /// 指定された例外が発生するか確認する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">実行する処理</param>
        /// <param name="testName">テスト項目名</param>
        private void CheckThrows<TException>(
            Action action,
            string testName)
            where TException : Exception
        {
            try
            {
                action();

                Check(false, testName);
            }
            catch (TException)
            {
                Check(true, testName);
            }
            catch (Exception exception)
            {
                Check(
                    false,
                    testName + "：" +
                    exception.GetType().Name);
            }
        }

        /// <summary>
        /// テスト結果を記録する。
        /// </summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>
        /// 自動テストの集計結果を出力する。
        /// </summary>
        private void PrintTestResult()
        {
            string message =
                "【InputDirectionUtility テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべてのテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        #endregion
    }
}
